"""Writes src/ink-aspect.js: width/height of every lifted design, so layouts reserve space before images load."""
import os, json, cv2
HERE = os.path.dirname(os.path.abspath(__file__)); SITE = os.path.dirname(HERE)
d = os.path.join(SITE, "public", "ink", "h")
out = {}
for f in sorted(os.listdir(d)):
    if f.endswith(".webp"):
        im = cv2.imread(os.path.join(d, f), cv2.IMREAD_UNCHANGED)
        out[f[:-5]] = round(im.shape[1] / im.shape[0], 3)
open(os.path.join(SITE, "src", "ink-aspect.js"), "w", encoding="utf8").write(
    "// GENERATED by scripts/ink-aspect.py: width / height of each lifted design (/ink/h/<file>.webp)\nexport const INK_ASPECT = " + json.dumps(out) + ";\n")
print(len(out))
